  /* ──────────────────  VALIDACIÓN DE BASE DE DATOS (SQL)  ────────────────── */

  sqlLab: {
    engine: 'Oracle 19c vía DBeaver',
    schema: 'CORE / LEGACY',
    queries: [
      {
        id: 'conciliacion',
        name: 'Conciliación de saldos legacy vs microservicio',
        goal: 'Detectar cuentas cuyo saldo migrado no coincide con el core COBOL.',
        verdict: 'fail',
        verdictLabel: '1.284 cuentas con descuadre → BDC-1042',
        sql: `SELECT  l.cta_numero              AS cuenta,
        l.cta_saldo               AS saldo_legacy,
        c.balance                 AS saldo_microservicio,
        (l.cta_saldo - c.balance) AS diferencia,
        c.migrated_at
FROM    LEGACY.CTA_SALDO  l
JOIN    CORE.SALDOS       c  ON c.account_id = l.cta_numero
WHERE   l.cta_saldo <> c.balance
  AND   c.migrated_at >= TRUNC(SYSDATE) - 1
ORDER BY ABS(l.cta_saldo - c.balance) DESC;`,
        columns: ['CUENTA', 'SALDO_LEGACY', 'SALDO_MICROSERVICIO', 'DIFERENCIA', 'MIGRATED_AT'],
        rows: [
          ['000199887766', '842.300,50', '842.300,00', '0,50', '2026-07-14 03:18:02'],
          ['000201445390', '1.209.887,75', '1.209.887,00', '0,75', '2026-07-14 03:18:05'],
          ['000188220114', '65.410,25', '65.410,00', '0,25', '2026-07-14 03:18:09'],
          ['000177003982', '3.980.115,50', '3.980.115,00', '0,50', '2026-07-14 03:18:12'],
        ],
        footer: '1284 rows retrieved — 412 ms',
        insight:
          'Todas las diferencias son fracciones menores a 1 peso: patrón claro de truncamiento de decimales, no de pérdida de movimientos. Ese dato acotó la investigación al mapper del job de migración.',
      },
      {
        id: 'duplicados',
        name: 'Movimientos duplicados por clave de idempotencia',
        goal: 'Verificar que un reintento no genere doble débito.',
        verdict: 'fail',
        verdictLabel: '2 movimientos para la misma clave → BDC-0987',
        sql: `SELECT  m.idempotency_key,
        COUNT(*)          AS movimientos,
        SUM(m.amount)     AS total_debitado,
        MIN(m.created_at) AS primer_intento,
        MAX(m.created_at) AS reintento
FROM    CORE.MOVIMIENTOS m
WHERE   m.created_at >= TIMESTAMP '2026-09-10 00:00:00'
GROUP BY m.idempotency_key
HAVING  COUNT(*) > 1
ORDER BY movimientos DESC;`,
        columns: ['IDEMPOTENCY_KEY', 'MOVIMIENTOS', 'TOTAL_DEBITADO', 'PRIMER_INTENTO', 'REINTENTO'],
        rows: [['f0b9d3e1-2c47-4a90-b1d5-6e83a7c4f210', '2', '500.000', '13:44:07.221', '13:44:12.884']],
        footer: '1 row retrieved — 88 ms',
        insight:
          'La diferencia de 5,6 s entre ambos registros coincidía con el timeout del gateway. Con ese dato el equipo ubicó el TTL del lock en Redis en minutos.',
      },
      {
        id: 'integridad',
        name: 'Integridad referencial post-migración',
        goal: 'Asegurar que no queden movimientos huérfanos sin cuenta asociada.',
        verdict: 'pass',
        verdictLabel: 'Sin registros huérfanos',
        sql: `SELECT  COUNT(*) AS movimientos_huerfanos
FROM    CORE.MOVIMIENTOS m
LEFT JOIN CORE.CUENTAS   c ON c.account_id = m.account_id
WHERE   c.account_id IS NULL;`,
        columns: ['MOVIMIENTOS_HUERFANOS'],
        rows: [['0']],
        footer: '1 row retrieved — 34 ms',
        insight:
          'Post-condición obligatoria de cada lote nocturno antes de habilitar el ambiente para las pruebas funcionales del día.',
      },
      {
        id: 'cuadratura',
        name: 'Cuadratura diaria por tipo de producto',
        goal: 'Comparar totales agregados entre ambos sistemas por familia de producto.',
        verdict: 'pass',
        verdictLabel: 'Diferencia total: 0,00',
        sql: `SELECT  c.product_type,
        COUNT(*)                          AS cuentas,
        SUM(c.balance)                    AS total_core,
        SUM(l.cta_saldo)                  AS total_legacy,
        SUM(c.balance) - SUM(l.cta_saldo) AS delta
FROM    CORE.SALDOS      c
JOIN    LEGACY.CTA_SALDO l ON l.cta_numero = c.account_id
GROUP BY c.product_type
ORDER BY delta DESC;`,
        columns: ['PRODUCT_TYPE', 'CUENTAS', 'TOTAL_CORE', 'TOTAL_LEGACY', 'DELTA'],
        rows: [
          ['CUENTA_CORRIENTE', '84.219', '412.887.330.115', '412.887.330.115', '0'],
          ['CUENTA_VISTA', '132.884', '98.220.417.880', '98.220.417.880', '0'],
          ['CUENTA_AHORRO', '41.007', '55.113.902.440', '55.113.902.440', '0'],
        ],
        footer: '3 rows retrieved — 1.204 ms',
        insight:
          'Ejecutada tras el fix de BDC-1042: la cuadratura global vuelve a cero, lo que habilitó la certificación del lote.',
      },
    ],
  },

